begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
insert into auth.users(id,email) values ('00000000-0000-4000-8000-000000226031','catalog-a@veyocast.test'),('00000000-0000-4000-8000-000000226032','catalog-b@veyocast.test');
insert into public.profiles(id,display_name) values ('00000000-0000-4000-8000-000000226031','Catalog A'),('00000000-0000-4000-8000-000000226032','Catalog B');
insert into public.tenants(id,name,slug) values ('10000000-0000-4000-8000-000000226031','Catalog A','catalog-a'),('10000000-0000-4000-8000-000000226032','Catalog B','catalog-b');
insert into public.tenant_memberships(tenant_id,user_id,role) values ('10000000-0000-4000-8000-000000226031','00000000-0000-4000-8000-000000226031','tenant_admin'),('10000000-0000-4000-8000-000000226032','00000000-0000-4000-8000-000000226032','tenant_viewer');
insert into public.tenant_products(tenant_id,slug,name,category,price_cents,active)
select '10000000-0000-4000-8000-000000226031','catalog-'||n,'Catalog '||lpad(n::text,4,'0'),case when n=1005 then 'Late category' else 'Drinks' end,200,n<>1005 from generate_series(1,1005) n;
insert into public.tenant_products(tenant_id,slug,name,category,price_cents) values ('10000000-0000-4000-8000-000000226032','secret','Other tenant secret','Secret category',900);
insert into public.tenant_products(tenant_id,slug,name,category,price_cents,deleted_at) values ('10000000-0000-4000-8000-000000226031','deleted','Deleted product','Deleted category',900,now());
update public.tenant_products set source_external_id='A,%_"B' where slug='catalog-1005' and tenant_id='10000000-0000-4000-8000-000000226031';
set local role anon;
select throws_ok($$select public.list_sync_products_v1('10000000-0000-4000-8000-000000226031')$$,'42501',null,'anonymous cannot call the catalog projection');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000226031',true);
select is((public.list_sync_products_v1('10000000-0000-4000-8000-000000226031')->>'total')::integer,1005,'complete total reaches beyond 1000 and excludes deleted products');
select is((public.list_sync_products_v1('10000000-0000-4000-8000-000000226031')->>'active')::integer,1004,'availability metric counts the complete tenant catalog');
select is(jsonb_array_length(public.list_sync_products_v1('10000000-0000-4000-8000-000000226031')->'rows'),50,'one response contains at most fifty products');
select is((public.list_sync_products_v1('10000000-0000-4000-8000-000000226031','','','all',1000)->>'count')::integer,1005,'last page carries the complete filtered count');
select is(jsonb_array_length(public.list_sync_products_v1('10000000-0000-4000-8000-000000226031','','','all',1000)->'rows'),5,'last page contains the final five original product identities');
select is(public.list_sync_products_v1('10000000-0000-4000-8000-000000226031','1005')->'rows'->0->>'name','Catalog 1005','search reaches beyond the first thousand rows');
select is((public.list_sync_products_v1('10000000-0000-4000-8000-000000226031','Late category')->>'count')::integer,1,'search includes a category outside the first page');
select is((public.list_sync_products_v1('10000000-0000-4000-8000-000000226031','%_"')->>'count')::integer,1,'wildcards quotes and commas remain literal bound search values');
select is((public.list_sync_products_v1('10000000-0000-4000-8000-000000226031','','Late category','inactive')->>'count')::integer,1,'category and availability filters are composed in the database');
select ok(public.list_sync_products_v1('10000000-0000-4000-8000-000000226031')->'categories' @> '["Late category"]','categories cover the complete tenant catalog');
select is((public.list_sync_products_v1('10000000-0000-4000-8000-000000226032')->>'total')::integer,0,'tenant A cannot obtain tenant B metrics');
select is(jsonb_array_length(public.list_sync_products_v1('10000000-0000-4000-8000-000000226032')->'categories'),0,'tenant A cannot obtain tenant B category names');
select throws_ok($$select public.list_sync_products_v1('10000000-0000-4000-8000-000000226031','','','all',-1)$$,'22023',null,'negative offset is rejected');
select throws_ok($$select public.list_sync_products_v1('10000000-0000-4000-8000-000000226031',repeat('x',121))$$,'22023',null,'oversize query is rejected');
select throws_ok($$select public.list_sync_products_v1('10000000-0000-4000-8000-000000226031','','','invalid')$$,'22023',null,'unknown availability cannot broaden a query');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000226032',true);
select is((public.list_sync_products_v1('10000000-0000-4000-8000-000000226032')->>'total')::integer,1,'viewer retains read access to the own catalog');
select is((public.list_sync_products_v1('10000000-0000-4000-8000-000000226031')->>'total')::integer,0,'tenant B cannot obtain tenant A metrics');
reset role;
select is((select prosecdef from pg_proc where oid='public.list_sync_products_v1(uuid,text,text,text,integer)'::regprocedure),false,'read helper remains SECURITY INVOKER');
select is(has_function_privilege('anon','public.list_sync_products_v1(uuid,text,text,text,integer)','EXECUTE'),false,'anonymous execution is explicitly revoked');
insert into public.tenant_products(tenant_id,slug,name,category,price_cents)
select '10000000-0000-4000-8000-000000226032','category-'||n,'Category '||n,'Category '||lpad(n::text,3,'0'),200 from generate_series(1,205) n;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000226032',true);
select is(jsonb_array_length(public.list_sync_products_v1('10000000-0000-4000-8000-000000226032')->'categories'),200,'category options remain bounded');
select is(public.list_sync_products_v1('10000000-0000-4000-8000-000000226032')->>'categoriesComplete','false','bounded category list explicitly reports incompleteness');
select is((public.list_sync_products_v1('10000000-0000-4000-8000-000000226032','Category 205')->>'count')::integer,1,'search still reaches a category outside the option list');
reset role;
select * from finish();
rollback;
